const raw = ($input.first().json.message?.text || '').trim();
const chatId = $input.first().json.message?.chat?.id;

const firstWordMatch = raw.match(/^(\S+)/);
const firstWord = firstWordMatch ? firstWordMatch[1].toLowerCase() : '';

// =====================================================
// PERMISSION
// =====================================================
function permissionFail(error) {
  return [{ json: { valid: false, type: 'permission', chatId, original: raw, error } }];
}

if (firstWord === 'permission') {
  let rest = raw.replace(/^permission\b/i, '').trim();

  if (!rest) {
    return permissionFail('Format: permission <time> <reason>. e.g. permission 10.00 AM Health issue');
  }

  const match = rest.match(/^(\d{1,2}[:.]\d{2}\s*(?:AM|PM|am|pm)?)\s+(.+)$/);

  if (!match) {
    return permissionFail('Format: permission <time> <reason>. e.g. permission 10.00 AM Health issue');
  }

  const time = match[1].trim().toUpperCase();
  const reason = match[2].trim();

  if (!reason) {
    return permissionFail('Please include a reason. e.g. permission 10.00 AM Health issue');
  }

  const now = new Date();
  const dateStr = [
    String(now.getDate()).padStart(2, '0'),
    String(now.getMonth() + 1).padStart(2, '0'),
    now.getFullYear()
  ].join('-');

  return [{
    json: { valid: true, type: 'permission', chatId, original: raw, date: dateStr, time, reason }
  }];
}

// =====================================================
// LEAVE
// =====================================================
function leaveFail(error) {
  return [{ json: { valid: false, type: 'leave', dates: [], chatId, original: raw, error } }];
}

if (firstWord !== 'leave') {
  return [{
    json: {
      valid: false,
      type: 'unknown',
      dates: [],
      chatId,
      original: raw,
      error: 'Message must start with "leave" or "permission".'
    }
  }];
}

let rest = raw.replace(/^leave\b/i, '').trim();
const leaveText = raw.replace(/^leave\b/i, '').trim();

if (!rest) {
  return leaveFail('No date provided.');
}

const months = {
  jan: 1, january: 1,
  feb: 2, february: 2,
  mar: 3, march: 3,
  apr: 4, april: 4,
  may: 5,
  jun: 6, june: 6,
  jul: 7, july: 7,
  aug: 8, august: 8,
  sep: 9, sept: 9, september: 9,
  oct: 10, october: 10,
  nov: 11, november: 11,
  dec: 12, december: 12
};

let year = null;
const yearMatch = rest.match(/(?:^|[\s,./-])(\d{4})\s*$/);

if (yearMatch) {
  year = Number(yearMatch[1]);
  rest = rest.slice(0, yearMatch.index).trim();
}

const monthRegex = /\b(january|february|march|april|may|june|july|august|september|sept|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|oct|nov|dec)\b/i;
const monthMatch = rest.match(monthRegex);

if (!monthMatch) {
  return leaveFail('A valid month is required.');
}

const monthName = monthMatch[1].toLowerCase();
const month = months[monthName];

const now = new Date();

if (year === null) {
  const currentYear = now.getFullYear();
  const currentMonth = now.getMonth() + 1;
  year = month >= currentMonth ? currentYear : currentYear + 1;
}

const dayPart = rest.slice(0, monthMatch.index).trim();

if (!dayPart) {
  return leaveFail('No day provided.');
}

const validSyntax = /^\s*\d{1,2}(?:\s*(?:,|to|-)\s*\d{1,2})*(?:\s*,)?\s*$/i;

if (!validSyntax.test(dayPart)) {
  return leaveFail('Invalid day format. Use formats like "20,21,22" or "12 to 16".');
}

const rangeMatch = dayPart.match(/^\s*(\d{1,2})\s*(?:to|-)\s*(\d{1,2})\s*$/i);
let dayNumbers = [];

if (rangeMatch) {
  const startDay = Number(rangeMatch[1]);
  const endDay = Number(rangeMatch[2]);

  if (startDay < 1 || startDay > 31) return leaveFail(`Invalid start day: ${startDay}.`);
  if (endDay < 1 || endDay > 31) return leaveFail(`Invalid end day: ${endDay}.`);
  if (startDay > endDay) return leaveFail('Start day cannot be greater than end day.');

  for (let day = startDay; day <= endDay; day++) {
    dayNumbers.push(day);
  }
} else {
  dayNumbers = [...dayPart.matchAll(/\d{1,2}/g)].map(m => Number(m[0]));
}

const lastDayOfMonth = new Date(year, month, 0).getDate();

for (const day of dayNumbers) {
  if (day < 1 || day > 31) return leaveFail(`Invalid day: ${day}. Day must be between 1 and 31.`);
  if (day > lastDayOfMonth) return leaveFail(`${day} is not a valid day for ${monthName} ${year}.`);
}

const validDates = dayNumbers.map(day => `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`);

return [{
  json: { valid: true, type: 'leave', dates: validDates, year, month: monthName, chatId, original: raw, leaveText }
}];
